/* xx_lzv1_extractor.c - search raw data for LZV1.
 *
 * Scans for:
 *   4C 5A 56 31 5D 19 01 AD 00 00 at +0  ("LZV1].....")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the lzv1 reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/lzv1/xx_lzv1.h"

static const uint8_t k_anchor0[] = { 0x4C, 0x5A, 0x56, 0x31, 0x5D, 0x19, 0x01, 0xAD, 0x00, 0x00 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_LZV1 };

static Abstractformat *xx_lzv1_search_open(xx_io_device *window) {
    xx_lzv1 *reader = xx_lzv1_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_lzv1_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_lzv1_free((xx_lzv1 *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_lzv1_search_open, xx_lzv1_search_close
};

static xx_format_search_state *xx_lzv1_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_lzv1_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_lzv1_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_lzv1_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_lzv1_extractor = {
    xx_lzv1_create_format_search,
    xx_lzv1_get_current_format_info,
    xx_lzv1_format_search_find_next,
    xx_lzv1_free_format_search
};
